# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.1/ankra-cli-darwin-arm64"
      sha256 "db6919c3b0379704265ad0d9b7452ab5411b313d348e2575278a3d6d68a50e84"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.1/ankra-cli-darwin-amd64"
      sha256 "8d8e751faadd01947faddbd77cf56177c7b674f9cfc54e9d4083a9d58303f126"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.78.1/ankra-cli-linux-arm64"
      sha256 "d27afe259722c7a172c82bf600f5e875bd74bcf57e81cf5d598142927befd510"
    end
    on_intel do
